cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout

  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _pricing = new();

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents()
    {
        var quote = _pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents()
    {
        var quote = _pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents()
    {
        var quote = _pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }

    // Bronze customer's reduction lands on a whole cent in their favour
    [Fact]
    public void S4_BronzeBasketOf7CentsIsCharged7Cents()
    {
        var quote = _pricing.Handle(new CalculateLoyaltyDiscountQuery(7, LoyaltyTier.Bronze));

        Assert.Equal(7, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest 2>&1 | grep -E "error|Failed|Assert|Expected|Actual|Passed!|Failed!" | head -30

